parent = []
rank = []

def findRoot(node):
	global parent
	while parent[node] != node:
		parent[node] = parent[parent[node]]
		node = parent[node]
	return node

def unionRoot(node1, node2):
	global parent, rank
	root1 = findRoot(node1)
	root2 = findRoot(node2)
	if root1 != root2:
		if rank[root1] > rank[root2]:
			parent[root2] = root1
		elif rank[root2] > rank[root1]:
			parent[root1] = root2
		else:
			parent[root1] = root2
			rank[root2] += 1
		return True
	else:
		return False

def kruskal(n, edges):
	global parent, rank
	parent = [node for node in range(n)]
	rank = [0] * n
	length = 0
	edges = sorted(edges, key=lambda x: x[0])
	n -= 1
	for (c, u, v) in edges:
		if unionRoot(u, v):
			length += c
			n -= 1
			if n == 0:
				break
	return length

def specialsum(mask, X):
	result = 0
	for (i, x) in zip(mask, X):
		if i == '0':
			result += x
		else:
			result -= x
	return result

def solve(N, D, points, specialdists):
	extrema = set([])
	for i in range(2 ** (D - 1)):
		(i_min, i_max) = (-1, -1)
		(d_min, d_max) = (float('inf'), -float('inf'))
		for index in range(N):
			d = specialdists[index][i]
			if d <= d_min:
				d_min = d
				i_min = index
			if d >= d_max:
				d_max = d
				i_max = index
		extrema.add((i_min, i))
		extrema.add((i_max, i))
	edges = []
	for (i, point) in enumerate(points):
		for (j, k) in extrema:
			if i != j:
				dist = abs(specialdists[i][k] - specialdists[j][k])
				edges.append((-dist, i, j))
	return -kruskal(N, edges)
